arguments.content:
* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: #1b1f2a;
  color: #e8eaf0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

#app {
  width: 800px;
  height: 600px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  padding: 16px;
  --cell: 64px;
}

h1 {
  font-size: 22px;
  margin: 8px 0;
}

#hud {
  display: flex;
  gap: 18px;
  margin-bottom: 6px;
  font-size: 16px;
  font-weight: 600;
}

.hud-item {
  padding: 4px 10px;
  background: #2a3040;
  border-radius: 6px;
}

#message {
  height: 22px;
  color: #ffd166;
  font-size: 15px;
  font-weight: 600;
}

#board {
  display: grid;
  gap: 2px;
  background: #0e1118;
  padding: 6px;
  border-radius: 8px;
}

.cell {
  width: var(--cell);
  height: var(--cell);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  position: relative;
}

.cell.wall { background: #3a4156; }
.cell.floor { background: #232a3a; }
.cell.start { background: #2c3550; }
.cell.exit { background: #1f6f43; }
.cell.coin { background: #2c3550; }
.cell.coin::after {
  content: "\25CF";
  color: #ffd166;
  font-size: 26px;
}
.cell.collected { background: #232a3a; }
.cell.exit::after {
  content: "E";
  color: #caffd0;
  font-weight: 700;
}
.cell.player::before {
  content: "";
  position: absolute;
  width: 60%;
  height: 60%;
  background: #4ea8ff;
  border-radius: 50%;
}

#controls {
  margin-top: 12px;
  display: flex;
  gap: 12px;
}

button {
  font-size: 16px;
  padding: 8px 18px;
  border: none;
  border-radius: 6px;
  background: #4ea8ff;
  color: #08121f;
  font-weight: 700;
  cursor: pointer;
}

button:hover { background: #6fb8ff; }

.hint {
  font-size: 13px;
  color: #9aa3b2;
  margin-top: 10px;
  text-align: center;
}

(function () {
  'use strict';

  // ---- Fixed 7x5 map ----
  // '#' wall, 'S' start (1,1), 'C' coin, 'E' exit (5,1)
  const MAP = [
    ['#', '#', '#', '#', '#', '#', '#'],
    ['#', 'S', '.', 'C', '.', 'E', '#'],
    ['#', '.', '#', '.', '#', '.', '#'],
    ['#', 'C', '.', '.', '.', 'C', '#'],
    ['#', '#', '#', '#', '#', '#', '#']
  ];
  const ROWS = MAP.length;        // 5
  const COLS = MAP[0].length;    // 7
  const START = { x: 1, y: 1 };
  const MAX_MOVES = 18;
  const TOTAL_COINS = 3;

  // ---- State ----
  let state = null;
  let collected = null;        // Set of "x,y"
  let currentTick = 0;
  let ready = false;
  let currentSeed = null;

  // ---- Event bridge ----
  let events = [];
  let seqCounter = 0;
  let event_epoch = 0;

  function emit(type, payload) {
    currentTick = performance.now();
    const ev = { seq: ++seqCounter, tick: currentTick, type: type };
    if (payload !== undefined && payload !== null) ev.payload = payload;
    events.push(ev);
    return ev;
  }

  function reset(opts) {
    opts = opts || {};
    event_epoch += 1;
    seqCounter = 0;
    events = [];
    collected = new Set();
    currentSeed = (opts && opts.seed !== undefined) ? opts.seed : null;
    state = {
      status: 'menu',
      player: { x: START.x, y: START.y },
      coins_collected: 0,
      moves_used: 0,
      moves_remaining: MAX_MOVES
    };
    currentTick = performance.now();
    emit('game_reset', {});
    renderBoard();
    updateHUD();
  }

  // ---- Helpers ----
  function key(x, y) { return x + ',' + y; }

  function isWall(x, y) {
    if (y < 0 || y >= ROWS || x < 0 || x >= COLS) return true;
    return MAP[y][x] === '#';
  }

  function cellAt(x, y) { return MAP[y][x]; }

  function doMove(nx, ny) {
    state.player.x = nx;
    state.player.y = ny;
    state.moves_used += 1;
    state.moves_remaining -= 1;
    emit('player_moved', { x: nx, y: ny });
  }

  function flashMessage(msg) {
    const m = document.getElementById('message');
    if (m) m.textContent = msg;
    if (flashMessage._t) clearTimeout(flashMessage._t);
    flashMessage._t = setTimeout(function () {
      const mm = document.getElementById('message');
      if (mm) mm.textContent = '';
    }, 900);
  }

  // ---- Movement ----
  function attemptMove(dx, dy) {
    if (!state || state.status !== 'playing') return;
    const nx = state.player.x + dx;
    const ny = state.player.y + dy;

    if (isWall(nx, ny)) {
      emit('wall_blocked', { x: nx, y: ny });
      flashMessage('Blocked by wall');
      updateHUD();
      return;
    }

    const c = cellAt(nx, ny);

    if (c === 'E') {
      if (state.coins_collected < TOTAL_COINS) {
        emit('exit_locked', {});
        flashMessage('Collect all coins first');
        updateHUD();
        return;
      }
      // Winning move: counts as a valid move into the exit.
      doMove(nx, ny);
      state.status = 'won';
      emit('game_won', {});
      renderBoard();
      updateHUD();
      return;
    }

    // Valid move onto floor or coin cell.
    doMove(nx, ny);
    if (c === 'C' && !collected.has(key(nx, ny))) {
      collected.add(key(nx, ny));
      state.coins_collected += 1;
      emit('coin_collected', { x: nx, y: ny });
    }
    if (state.moves_used >= MAX_MOVES && state.status === 'playing') {
      state.status = 'lost';
      emit('game_lost', {});
    }
    renderBoard();
    updateHUD();
  }

  function startGame() {
    if (!state) return;
    if (state.status === 'menu') {
      state.status = 'playing';
      emit('game_started', {});
      updateHUD();
    }
  }

  function restartGame() {
    reset({ seed: currentSeed });
  }

  // ---- Rendering ----
  let cellEls = [];

  function buildBoard() {
    const board = document.getElementById('board');
    board.innerHTML = '';
    cellEls = [];
    board.style.gridTemplateColumns = 'repeat(' + COLS + ', var(--cell))';
    board.style.gridTemplateRows = 'repeat(' + ROWS + ', var(--cell))';
    for (let y = 0; y < ROWS; y++) {
      const row = [];
      for (let x = 0; x < COLS; x++) {
        const d = document.createElement('div');
        d.className = 'cell';
        d.dataset.x = x;
        d.dataset.y = y;
        board.appendChild(d);
        row.push(d);
      }
      cellEls.push(row);
    }
  }

  function renderBoard() {
    if (!cellEls.length) buildBoard();
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        const el = cellEls[y][x];
        const c = MAP[y][x];
        let cls = 'cell';
        if (c === '#') {
          cls += ' wall';
        } else if (c === 'E') {
          cls += ' exit';
        } else if (c === 'C') {
          if (collected && collected.has(key(x, y))) cls += ' collected';
          else cls += ' coin';
        } else {
          cls += ' floor';
          if (c === 'S') cls += ' start';
        }
        if (state.player.x === x && state.player.y === y) cls += ' player';
        el.className = cls;
      }
    }
  }

  function updateHUD() {
    const score = document.querySelector('[data-testid="score"]');
    const statusEl = document.querySelector('[data-testid="status"]');
    const movesEl = document.getElementById('moves');
    if (score) score.textContent = 'Coins: ' + state.coins_collected + '/' + TOTAL_COINS;
    if (statusEl) statusEl.textContent = state.status;
    if (movesEl) movesEl.textContent = 'Moves: ' + state.moves_used + '/' + MAX_MOVES;
  }

  // ---- Read-only observation bridge (gametestlab/2) ----
  window.__GAMETESTLAB__ = {
    protocol: 'gametestlab/2',
    isReady: function () { return ready; },
    reset: function (opts) { reset(opts); return observe(); },
    observe: function () {
      return {
        tick: currentTick,
        status: state.status,
        state: JSON.parse(JSON.stringify(state)),
        event_epoch: event_epoch,
        latest_event_seq: seqCounter
      };
    },
    getEvents: function (opts) {
      opts = opts || {};
      const after = (opts.afterSeq !== undefined) ? opts.afterSeq : 0;
      return events.filter(function (e) { return e.seq > after; });
    }
  };

  // ---- Init ----
  function init() {
    buildBoard();
    reset({});
    ready = true;

    // Time driven by requestAnimationFrame (virtual-time friendly).
    function loop() {
      currentTick = performance.now();
      requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);

    document.getElementById('start-btn').addEventListener('click', startGame);
    document.getElementById('restart-btn').addEventListener('click', restartGame);

    window.addEventListener('keydown', function (e) {
      switch (e.code) {
        case 'ArrowUp': e.preventDefault(); attemptMove(0, -1); break;
        case 'ArrowDown': e.preventDefault(); attemptMove(0, 1); break;
        case 'ArrowLeft': e.preventDefault(); attemptMove(-1, 0); break;
        case 'ArrowRight': e.preventDefault(); attemptMove(1, 0); break;
        case 'KeyR': e.preventDefault(); restartGame(); break;
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

{
  "schema_version": "gametestlab.game-manifest.v3",
  "entry_path": "index.html",
  "surface": "dom",
  "viewport": { "width": 800, "height": 600 },
  "controls": [
    { "action_id": "START", "actor": "primary", "device": "mouse", "key_event": "press", "selector": "#start-btn", "description": "开始游戏" },
    { "action_id": "UP", "actor": "primary", "device": "keyboard", "key_event": "down", "code": "ArrowUp", "description": "向上移动" },
    { "action_id": "DOWN", "actor": "primary", "device": "keyboard", "key_event": "down", "code": "ArrowDown", "description": "向下移动" },
    { "action_id": "LEFT", "actor": "primary", "device": "keyboard", "key_event": "down", "code": "ArrowLeft", "description": "向左移动" },
    { "action_id": "RIGHT", "actor": "primary", "device": "keyboard", "key_event": "down", "code": "ArrowRight", "description": "向右移动" },
    { "action_id": "RESTART", "actor": "primary", "device": "mouse", "key_event": "press", "selector": "#restart-btn", "description": "重新开始" },
    { "action_id": "RESTART_KEY", "actor": "primary", "device": "keyboard", "key_event": "down", "code": "KeyR", "description": "按 R 重新开始" }
  ],
  "hud_selectors": {
    "score": "[data-testid=\"score\"]",
    "status": "[data-testid=\"status\"]"
  },
  "state_schema": {
    "fields": {
      "status": { "type": "string", "description": "当前状态" },
      "player": { "type": "object", "description": "玩家坐标", "properties": { "x": { "type": "integer", "description": "x 坐标" }, "y": { "type": "integer", "description": "y 坐标" } } },
      "coins_collected": { "type": "integer", "description": "已收集金币数" },
      "moves_used": { "type": "integer", "description": "已使用有效移动数" },
      "moves_remaining": { "type": "integer", "description": "剩余有效移动数" }
    },
    "required": ["status", "player", "coins_collected", "moves_used", "moves_remaining"]
  },
  "event_schema": [
    { "type": "game_started", "description": "游戏开始", "payload_fields": {} },
    { "type": "player_moved", "description": "玩家移动", "payload_fields": { "x": { "type": "integer", "description": "目标 x" }, "y": { "type": "integer", "description": "目标 y" } } },
    { "type": "wall_blocked", "description": "撞墙被阻挡", "payload_fields": { "x": { "type": "integer", "description": "目标 x" }, "y": { "type": "integer", "description": "目标 y" } } },
    { "type": "coin_collected", "description": "收集金币", "payload_fields": { "x": { "type": "integer", "description": "金币 x" }, "y": { "type": "integer", "description": "金币 y" } } },
    { "type": "exit_locked", "description": "金币不足时碰出口", "payload_fields": {} },
    { "type": "game_won", "description": "获胜", "payload_fields": {} },
    { "type": "game_lost", "description": "失败", "payload_fields": {} },
    { "type": "game_reset", "description": "复位到菜单", "payload_fields": {} }
  ],
  "bridge": {
    "protocol": "gametestlab/2",
    "evidence_only": true,
    "actions_via_real_input": true
  }
}
